descriptor.templateCss:
.card-container {
    background-color: #1a222c;
    border-radius: 12px;
    padding: 16px;
    color: #fff;
    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    border: 1px solid #2a3545;
    box-sizing: border-box;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.title {
    color: #00d285;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.5px;
}

.badge {
    background-color: #00d285;
    color: #1a222c;
    padding: 4px 10px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: bold;
}

.card-body {
    margin: 15px 0;
}

.status-text {
    color: #00d285;
    font-size: 32px;
    font-weight: bold;
    text-transform: uppercase;
}

.card-footer {
    display: flex;
    justify-content: space-between;
    font-size: 11px;
    color: #8c97a8;
}

.highlight {
    color: #fff;
}

/* Dynamic Styles: เปลี่ยนสีเมื่อหยุดทำงาน */
.status-stop .title,
.status-stop .status-text {
    color: #ff5b5b;
}
.status-stop .badge {
    background-color: #ff5b5b;
}

descriptor.controllerScript:
self.onInit = function() {
    self.ctx.$scope.status = 'RUN (ฉีดผลิต)';
    self.ctx.$scope.ctSignal = '84.2';
    self.ctx.$scope.isRun = true;
};

self.onDataUpdated = function() {
    if (self.ctx.data.length > 0) {
        for (var i = 0; i < self.ctx.data.length; i++) {
            var cellData = self.ctx.data[i];
            if (cellData.data.length > 0) {
                var val = cellData.data[0][1];
                var key = cellData.dataKey.name;

                if (key === 'status') {
                    self.ctx.$scope.status = val;
                    self.ctx.$scope.isRun = (String(val).toUpperCase() === 'RUN' || String(val).indexOf('ฉีดผลิต') !== -1 || val === '1' || val === true);
                }
                if (key === 'ct_signal') {
                    self.ctx.$scope.ctSignal = Number(val).toFixed(1);
                }
            }
        }
        self.ctx.$scope.$digest();
    }
};
